\cite{Opial1967} \label{lem2.2}
    Consider a nonempty subset $C$ of $\mathcal{H}$. Let $\{\tau_n\}_n$ be a sequence in $\mathcal{H}$ such that the following two conditions hold
    \begin{itemize}
        \item [(i)] for all $\zeta\in C$, $\lim_{n\to +\infty}\|\tau_n-\zeta\|$ exists,
        \item [(ii)] every sequential weak cluster point of $\{\tau_n\}_n$ is in $C$.
    \end{itemize}
    Then the sequence $\{\tau_n\}_n$ converges weakly to a point in $C$.

\label{re2}
In the literature, one can find some iterative methods (i.e. inertial Douglas-Rachford type algorithms) that look similar to Algorithm \ref{P4Al4.11}, however, there are some subtle differences between them that are highlighted below.
\cite[Algorithm 2]{HDO} has a similar definition; however, it allows only certain values for $\{\theta_n\}_n$ that are derived iteratively, as they depend on the other generated sequences, while Algorithm \ref{P4Al4.11} allows much more flexibility, as $\{\theta_n\}_n \subseteq (0,1)$ can  even be a priori fixed. This permits additional investigations on our algorithm in order to identify optimal choices of the inertial parameters. On the other hand, the inertial DR type algorithms proposed in \cite{YJS} contain an additional sequence to the ones required by our Algorithm \ref{P4Al4.11}, whose handling increases the running time and, consequently, the associated costs, as revealed by the numerical experiments presented in Section \ref{section5}. The mentioned feature brings Algorithm \ref{P4Al4.11} closer to the original inertial DR algorithm than its counterparts. Moreover, the construction we propose makes the coefficient of $x_n$ in the inertial term (where $u_n$ is defined) belong to the interval $(1,2)$, while in \cite[Algorithm 2]{YJS} it lies in $[0, 1)$. One could also mention \cite[Algorithm 1]{chuang2022unified} in this context; however, it is a ``pure'' DR type method, without inertial steps.

\label{lem3.1}
    Considering $w \in \Omega_{GDPC}$, there exists a $y\in \Gamma_\beta$ such that the sequences generated by Algorithm \ref{P4Al4.11} satisfy
     \begin{align}\label{e13}
        (1+\beta\rho)\|y_n-w\|^2\le \langle y_n-w, u_n-y \rangle\ \forall n \in \mathbb{N}.
    \end{align}

From the way Algorithm \ref{P4Al4.11} is defined, we have for a fixed $n\geq 1$ that (via \eqref{id2})
    \begin{align}\label{eq3.10}
        &y_n=(\operatorname*{Id}+\beta \partial \phi)^{-1}(u_n)\nonumber\\
        \Rightarrow&\frac{1}{\beta}(u_n-y_n)\in \partial \phi(y_n).
    \end{align}
    and
    $$              
        z_n=(\operatorname*{Id}+\beta \partial g)^{-1}(2y_n-u_n+\beta \nabla h(y_n))$$   
       \begin{align}\label{eq6} \Rightarrow \nabla h(y_n)+\frac{1}{\beta}(2y_n-u_n-z_n)\in \partial g (z_n).
    \end{align}
    Consider $w \in \Omega_{GDPC}$. Using relation \eqref{en1.3}, we have a $y \in \mathcal{H}$ such that
    \begin{align}\label{eq3.13}
        \frac{1}{\beta}(y-w)\in \partial \phi(w),
    \end{align} and
     \begin{equation}\label{eq2}
            \frac{1}{\beta}(w-y)+\nabla h(w) \in \partial g(w).
    \end{equation}
From \eqref{eq3.13} and \eqref{eq2}, one can derive
$y\in \Gamma_\beta (w)$.
    As $\phi$ is strongly convex (see Remark \ref{re1}),                                 
    \begin{align*}
        \rho\|y_n-w\|^2&\le \langle y_n-w,\theta-\alpha
        \rangle\ \forall \theta\in \partial \phi (y_n)\ \forall \alpha\in \partial\phi (w).
    \end{align*}
Using relations \eqref{eq3.10} and \eqref{eq3.13}, we have
    \begin{align*}
        \rho\|y_n-w\|^2&\le \frac{1}{\beta}\langle y_n-w, u_n-y_n-y+w\rangle\\
        &=\frac{1}{\beta}\langle y_n-w, u_n-y\rangle-\frac{1}{\beta}\|y_n-w\|^2,
    \end{align*}
    which implies \eqref{e13}.

\label{pr1}
Let $\{x_n\}_n$, $\{u_n\}_n$, $\{y_n\}_n$ and $\{z_n\}_n$ be sequences generated by Algorithm \ref{P4Al4.11}, and assume that
\begin{equation}\label{e15}
0<\underline\kappa\le\kappa_n\le\overline\kappa<2,
\end{equation}
and
\begin{equation}\label{e16}
 \bar\theta = \sup_{n\ge 1} \theta_n <1,\ \Theta=\sum_{n=1}^{+\infty}\theta_n<+\infty.
\end{equation}
Then $\sum_{n=1}^{+\infty}\|x_n-x_{n-1}\|^2 < +\infty$.

\label{L3.3}
    Given $ x^* \in \mathcal{H}$, one has $x^* \in \Omega_{PDRDC}$ if and only if there exists a $y\in \mathcal{H} $ satisfying
    \begin{enumerate}

         \item[(i)]   $ x^* = \operatorname{prox}_{\phi}(y)$

        \item[(ii)] $ x^* =\operatorname{prox}_{ g}(\alpha x^* -y+\nabla h(x^*))$.

    \end{enumerate}

By construction, $x^*$ is a solution of \eqref{P3.2} if there exists $y\in \mathcal{H}$ such that
   $$y-x^* \in \partial\phi(x^*)  \text{ and } x^* -y+\nabla h(x^*)\in \partial g(x^*)+(2-\alpha)x^*,$$
   which is further equivalent to
$$                
       y \in  x^* + \partial\phi(x^*)  \text{ and } \alpha x^* -y+\nabla h(x^*)\in x^*+\partial g(x^*)=(\operatorname*{Id}+  \partial g)(x^*)$$
and, finally, to
\begin{equation}\label{eq66}

\left\{
\begin{array}{l}
x^* = \operatorname{prox}_{ \phi} (y)\\
x^*= \operatorname{prox}_{ g} (\alpha x^* - y +  \nabla h(x^*)).
\end{array}
\right.
\end{equation}

\label{lem4.2}
    Consider $w \in \Omega_{PDRDC}$ and $y \in \mathcal{Z}(w)$, then sequences $\{u_n\}_n \text{ and } \{y_n\}$ generated by Algorithm \ref{P4Al4.1} satisfy the following inequality
    \begin{equation}\label{eq23}
        (1+\rho)\|y_n -w\|^2 \leq \langle y_n-w,u_n-y \rangle\ \forall n \in \mathbb{N}
    \end{equation}

Since $w \in \Omega_{PDRDC}$, from  \eqref{eq66}, we have
    \begin{align}\label{eqn24}
       & w=\operatorname{prox}_{\phi}(y) \iff (\operatorname*{Id}+\partial \phi)(w) = y \iff y-w \in \partial \phi (w).
    \end{align}
   Let $n\in \mathbb{N}$. From Algorithm \ref{P4Al4.1}, we have
   \begin{align}\label{eqn25}
    &y_n =\operatorname{prox}_{\phi}(u_n) \iff y_n + \partial \phi (y_n) = u_n \iff u_n-y_n \in \partial{\phi} (y_n).
   \end{align}

Since $\phi$ is $\rho$-strongly convex, we have
\begin{align*}
    \rho\|y_n -w\|^2 \leq \langle y_n -w, \theta -\alpha \rangle \ \forall \theta \in \partial (y_n) \ \forall  \alpha \in \partial (w).
     \end{align*}
From equations \eqref{eqn24} and \eqref{eqn25}, one has
\begin{align}
    \rho\|y_n -w\|^2 &\leq \langle y_n-w, u_n-y_n-y+w \rangle\nonumber\\
    &= \langle y_n-w, u_n-y \rangle - \| y_n-w \|^2, \nonumber\end{align}
   which yields \eqref{eq23}.

\label{pr2}
Let $\{x_n\}_n$, $\{u_n\}_n$, $\{y_n\}_n$ and $\{z_n\}_n$ be sequences generated by Algorithm \ref{P4Al4.1}, and assume that

\begin{equation}\label{e16.1}
 \bar\theta = \sup_{n\ge 1} \theta_n <1,\ \Theta=\sum_{n=1}^{+\infty}\theta_n<+\infty.
\end{equation}
Then $\sum_{n=1}^{+\infty}\|x_n-x_{n-1}\|^2 < +\infty$.
